67	lv_obj_t * lv_tileview_add_tile(lv_obj_t * tv, uint8_t col_id, uint8_t row_id, lv_dir_t dir)
68	{
69	    LV_LOG_INFO("begin");
70	
71	    lv_obj_t * obj = lv_obj_class_create_obj(&lv_tileview_tile_class, tv);
72	    lv_obj_class_init_obj(obj);
