84	void lv_tileview_set_tile(lv_obj_t * obj, lv_obj_t * tile_obj, lv_anim_enable_t anim_en)
85	{
86	    int32_t tx = lv_obj_get_x(tile_obj);
87	    int32_t ty = lv_obj_get_y(tile_obj);
88	
89	    lv_tileview_tile_t * tile = (lv_tileview_tile_t *)tile_obj;
90	    lv_tileview_t * tv = (lv_tileview_t *) obj;
91	    tv->tile_act = (lv_obj_t *)tile;
92	
93	    lv_obj_set_scroll_dir(obj, tile->dir);
94	    lv_obj_scroll_to(obj, tx, ty, anim_en);
95	}
